package br.com.coleta.sistemas.agendaecapacidade.Consumer;
import br.com.coleta.sistemas.agendaecapacidade.Dto.*; import br.com.coleta.sistemas.agendaecapacidade.Entity.*; import br.com.coleta.sistemas.agendaecapacidade.Repository.*; import br.com.coleta.sistemas.agendaecapacidade.Service.*;
import org.springframework.amqp.rabbit.annotation.RabbitListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import tools.jackson.databind.ObjectMapper; import lombok.RequiredArgsConstructor; import java.util.*; import java.time.*;
@Component @RequiredArgsConstructor public class SolicitacaoCriadaConsumer {
 private final ObjectMapper mapper; private final AgendaService service; private final OutboxEventoService outbox; private final MensagemProcessadaRepository inbox; private final AgendaRepository agendas; private final CapacidadeAgendaRepository capacidades;
 @RabbitListener(queues="agenda.criada") @Transactional public void receber(String body){var e=mapper.readValue(body,Envelope.class);e.validar("SolicitacaoCriada");var id=e.id("solicitacaoId");var bairro=(String)e.payload().get("bairro");var data=LocalDate.parse((String)e.payload().get("dataColeta"));if(bairro==null||bairro.isBlank())throw new IllegalArgumentException("bairro");if(!inbox.registrarSeNovo(e.messageId().toString(),e.type()))return;Map<String,Object> p=new HashMap<>();p.put("solicitacaoId",id);try{var r=service.reservar(new AgendaRequestsDTO(id,bairro,data));p.put("reservada",r.status()!=AgendaReserva.LIBERADA);p.put("reservaId",r.id());}catch(IllegalStateException ex){p.put("reservada",false);}outbox.registrarEvento(id,"reserva.resultado",mapper.writeValueAsString(Envelope.criar(e.correlationId(),"ResultadoReserva",p)));}
 @RabbitListener(queues="agenda.liberar") @Transactional public void liberar(String body){var e=mapper.readValue(body,Envelope.class);e.validar("LiberarReserva");if(!inbox.registrarSeNovo(e.messageId().toString(),e.type()))return;agendas.findBySolicitacaoId(e.id("solicitacaoId")).ifPresent(a->{if(a.getStatus()==AgendaReserva.RESERVADA){capacidades.liberarVaga(a.getBairro(),a.getDataColeta());a.liberar();}});}
 @RabbitListener(queues="agenda.confirmada") @Transactional public void confirmar(String body){var e=mapper.readValue(body,Envelope.class);e.validar("ColetaConfirmada");if(!inbox.registrarSeNovo(e.messageId().toString(),e.type()))return;var a=agendas.findBySolicitacaoId(e.id("solicitacaoId")).orElseThrow();if(!a.getId().equals(e.id("reservaId")))throw new IllegalArgumentException("reserva divergente");if(a.getStatus()==AgendaReserva.RESERVADA)a.efetivar();}
}